package com.mohymods.kingdomsmp.profession;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
class ProfessionEvidenceTest {
 @Test void scopedFilesCannotCreditAnotherProfessionAndActorsRemainIsolated(){var player=UUID.randomUUID();var metrics=Set.of("natural_iron");var evidence=new ProfessionEvidence(Profession.MINER,metrics);assertTrue(evidence.record(player,ProfessionRank.APPRENTICE,"natural_iron",1,"minecraft:overworld/123"));var saved=evidence.save();assertThrows(IllegalArgumentException.class,()->ProfessionEvidence.load(saved,Profession.FARMER,metrics));var restored=ProfessionEvidence.load(saved,Profession.MINER,metrics);assertEquals(1,restored.count(player,ProfessionRank.APPRENTICE,"natural_iron"));assertEquals(0,restored.count(UUID.randomUUID(),ProfessionRank.APPRENTICE,"natural_iron"));assertFalse(restored.record(player,ProfessionRank.JOURNEYMAN,"natural_iron",1,"minecraft:overworld/123"));}
 @Test void farmerLegacySchemaAndProofsRoundTripWithoutConversion(){var player=UUID.randomUUID();var counters=new CompoundTag();counters.putInt("apprentice/soil",7);var seen=new ListTag();seen.add(StringTag.valueOf("soil:minecraft:overworld/42"));var row=new CompoundTag();row.putUUID("player",player);row.put("counters",counters);row.put("unique",seen);var rows=new ListTag();rows.add(row);var legacy=new CompoundTag();legacy.putInt("schema",1);legacy.put("players",rows);var restored=FarmerEvidence.load(legacy);assertEquals(legacy,restored.save());assertEquals(7,restored.count(player,ProfessionRank.APPRENTICE,"soil"));assertFalse(restored.record(player,ProfessionRank.MASTER,"soil",1,"minecraft:overworld/42"));assertEquals(legacy,restored.save());}
 @Test void unknownMetricsNegativeCountsAndForeignRowsAreRejected(){var player=UUID.randomUUID();var e=new ProfessionEvidence(Profession.BUILDER,Set.of("retained_blocks"));assertThrows(IllegalArgumentException.class,()->e.record(player,ProfessionRank.APPRENTICE,"unregistered",1,null));assertThrows(IllegalArgumentException.class,()->e.record(player,ProfessionRank.APPRENTICE,"retained_blocks",0,null));e.record(player,ProfessionRank.APPRENTICE,"retained_blocks",1,"world/1");var data=e.save();data.getCompound("evidence").getList("players",Tag.TAG_COMPOUND).getCompound(0).getCompound("counters").putInt("apprentice/retained_blocks",-1);assertThrows(IllegalArgumentException.class,()->ProfessionEvidence.load(data,Profession.BUILDER,Set.of("retained_blocks")));}
 @Test void proofCapacityNeverEvictsIntoRecountableState(){var player=UUID.randomUUID();var e=new ProfessionEvidence(Profession.MINER,Set.of("ore"));for(int n=0;n<ProfessionEvidence.MAX_UNIQUE;n++)assertTrue(e.record(player,ProfessionRank.APPRENTICE,"ore",1,Integer.toString(n)));assertFalse(e.record(player,ProfessionRank.APPRENTICE,"ore",1,"new"));assertFalse(e.record(player,ProfessionRank.MASTER,"ore",1,"0"));var restored=ProfessionEvidence.load(e.save(),Profession.MINER,Set.of("ore"));assertEquals(ProfessionEvidence.MAX_UNIQUE,restored.count(player,ProfessionRank.APPRENTICE,"ore"));assertFalse(restored.record(player,ProfessionRank.APPRENTICE,"ore",1,"new"));}
}
